const fmtFormulaHTML=f=>(f.text||'').replace(/(\d+)/g,'<sub>$1</sub>')+(f.charge?`<sup>${Math.abs(f.charge)>1?Math.abs(f.charge):''}${f.charge>0?'+':'−'}</sup>`:'');

