  if(f.id==='trForm'){e.preventDefault();e.stopImmediatePropagation();const v=($('#trIn').value||'').trim();if(!v)return;trAnswer({t:v.slice(0,120)});if(TC.run&&TC.run.mode==='test'){toast('Answer saved.')}return}
